.notice--warning { border-left-color: var(--cms-color-error); background: var(--cms-color-surface); }
.notice--neutral { border-left-color: var(--cms-color-text-subtle); background: var(--cms-color-surface); }
.notice__title { margin: 0 0 0.5rem; font-size: 1.25rem; line-height: 1.3; }
.notice__text { color: var(--cms-color-text-muted); }
.notice__text > :first-child { margin-top: 0; }
.notice__text > :last-child { margin-bottom: 0; }
.notice__action { margin: 0.75rem 0 0; }
.notice__link { color: var(--cms-color-accent-strong); font-weight: 600; text-decoration: underline; text-underline-offset: 0.2em; transition: color 0.2s ease; }
.notice__link:hover { color: var(--cms-color-text); }
.notice__link:focus-visible { color: var(--cms-color-text); outline: 2px solid var(--cms-color-accent); outline-offset: 2px; }
@media (min-width: 48rem) { .notice { padding: 1.5rem 2rem 1.5rem 2.25rem; } .notice__title { font-size: 1.375rem; } }"}

